class Random {
  constructor() {
    this.useA = false;
    let sfc32 = function (uint128Hex) {
      let a = parseInt(uint128Hex.substring(0, 8), 16);
      let b = parseInt(uint128Hex.substring(8, 16), 16);
      let c = parseInt(uint128Hex.substring(16, 24), 16);
      let d = parseInt(uint128Hex.substring(24, 32), 16);
      return function () {
        a |= 0;
        b |= 0;
        c |= 0;
        d |= 0;
        let t = (((a + b) | 0) + d) | 0;
        d = (d + 1) | 0;
        a = b ^ (b >>> 9);
        b = (c + (c << 3)) | 0;
        c = (c << 21) | (c >>> 11);
        c = (c + t) | 0;
        return (t >>> 0) / 4294967296;
      };
    };
    // seed prngA with first half of tokenData.hash
    this.prngA = new sfc32(tokenData.hash.substring(2, 34));
    // seed prngB with second half of tokenData.hash
    this.prngB = new sfc32(tokenData.hash.substring(34, 66));
    for (let i = 0; i < 1e6; i += 2) {
      this.prngA();
      this.prngB();
    }
  }
  // random number between 0 (inclusive) and 1 (exclusive)
  random_dec() {
    this.useA = !this.useA;
    return this.useA ? this.prngA() : this.prngB();
  }
  // random number between a (inclusive) and b (exclusive)
  random_num(a, b) {
    return a + (b - a) * this.random_dec();
  }
  // random integer between a (inclusive) and b (inclusive)
  // requires a < b for proper probability distribution
  random_int(a, b) {
    return Math.floor(this.random_num(a, b + 1));
  }
  // random boolean with p as percent liklihood of true
  random_bool(p) {
    return this.random_dec() < p;
  }
  // random value in an array of items
  random_choice(list) {
    return list[this.random_int(0, list.length - 1)];
  }
}

let R = new Random();

let numLines = 2500;
let maxNumLines = 1500;
let radius = 5;
let angleOffset;
let moveX;
let farbe1;
let farbe2;
let drawingTime = 2000;
let stopped = false;
let rectColor;
let amplitude = 0;
let pulsatingColor;
let pulseSpeed = 1.02;
let radiusBreite = 100;
let radiusHöhe = 80;
let hintergrund;
let lineX;
let lineY;
let angelX;
let angelY;

let moveXY;

let line1 = false;
let line2 = false;

let rectMode = false;
let circleMode = false;
let lineMode = true;

let zufall;
let randColor;

// Define variables for background color change
let startBackgroundColor;
let targetBackgroundColor;
let backgroundColorChangeDuration = 30000; // 10 seconds

let startTime;
let changeColor = 10;

let randomCircle = false;
let randomRect = false;
let randomLines = false;


function setup() {
  createCanvas(windowWidth / 1.1, windowHeight / 1.1);
  angleMode(DEGREES);
  noFill();
  initializeParameters();
  numLines = R.random_num(200, 2500);
  hintergrund = random(0, 220);
  lineX = R.random_num(100, 500);
  lineY = R.random_num(100, 500);
  angelX = R.random_num(280, 360);
  angelY = R.random_num(1, 140);
  radiusBreite = width / 8;
  radiusHöhe = height / 8;
  moveXY = R.random_num(1, 20);

  farbe1 = color(R.random_num(1,255), R.random_num(1,255), R.random_num(1,255));
  farbe2 = color(R.random_num(1,255), R.random_num(1,255), R.random_num(1,255));
  rectColor = color(255, 228, 196);
  pulsatingColor = color(320, 30, 30);

  zufall = R.random_int(1,10);
  randColor = R.random_num(1, 10);

  // Set a timeout to stop drawing after the specified time
  setTimeout(stopDrawing, drawingTime);

  // Set initial background colors
  //startBackgroundColor = color(0);
  //targetBackgroundColor = color(200);

  // Set start time
  startTime = millis();
}

function draw() {
  // Pulsierender Hintergrund
  pulsatingColor.setRed(30 + 20 * sin(frameCount * pulseSpeed));
  pulsatingColor.setGreen(30 + 20 * sin(frameCount * pulseSpeed + PI / 3));
  pulsatingColor.setBlue(30 + 20 * sin(frameCount * pulseSpeed + 2 * PI / 3));

  // Interpolate background color based on elapsed time
  //let elapsedTime = millis() - startTime;
  //let backgroundInterpolation = constrain(elapsedTime / backgroundColorChangeDuration, 0, 1);
  //let currentBackgroundColor = lerpColor(startBackgroundColor, targetBackgroundColor, backgroundInterpolation);

  // Set background color
  //background(currentBackgroundColor);
background(200);
  translate(width / 2, height / 2);

  for (let i = 0; i < numLines; i++) {
    let angle = map(i, 0, numLines, 0, angelX);

    let p1 = createVector(
      cos(angle + angleOffset) * radius * angelY,
      sin(angle + angleOffset) * (radius + sin(angle + angleOffset))
    );
    let p2 = createVector(
      cos(angle * moveX + angleOffset) * (radius + width / 3),
      sin(angle * 3 + angleOffset) * (radius + radiusBreite + sin(angle * moveX) * radiusHöhe)
    );

    // Füge die Sinus-Bewegung für die y-Koordinaten hinzu
    p1.y += amplitude * sin(angleOffset * 2);
    p2.y += amplitude * sin(angleOffset * 2);

    let colR = map(p2.x, -width / 2, width / 2, 0, farbe1.levels[0]);
    let colG = map(p2.y, -height / 2, height / 2, 0, farbe2.levels[1]);
    let colB = map(i, 0, numLines, 0, farbe1.levels[2]);
    let alpha = map(i, 0, numLines, 150, 255);
    let weight = map(sin(angleOffset * 0.5), -1, 1, 0.1, 1);

    if (zufall >= 7 && zufall <= 10) { // rectMode

      randomRect = true;

      stroke(colR * 2, colG * 2, colB, alpha);
      strokeWeight(0.1);
      rect(p1.x * lineX, p1.y, p2.x, p2.y);
      stroke(40);
      rect(p1.x * lineX, p1.y + 3, p2.x, p2.y);
    }

    if (zufall === 6) { //circleMode

      randomCircle = true;
      //numLines = 100;
      stroke(colR * randColor, colG * 3, colB, alpha);
      strokeWeight(0.6);
      circle(p1.x - width / 4, p1.y, p2.x / 2, p2.y);
      stroke(0);
      circle(p1.x - width / 4, p1.y + 1, p2.x / 2, p2.y + 3);
      
     // numLines = 200;
      changeColor += 0.1;
      stroke(changeColor, colG * randColor, colB, alpha);
      strokeWeight(0.1);
      circle(p1.x, p1.y, p2.x / 2, p2.y);
      stroke(0);
      circle(p1.x, p1.y + 1, p2.x / 2, p2.y + 3);

      //numLines = 100;
      stroke(colR * randColor, colG * 3, colB, alpha);
      strokeWeight(0.6);
      circle(p1.x + width / 4, p1.y, p2.x / 2, p2.y);
      stroke(0);
      circle(p1.x + width / 4, p1.y + 1, p2.x / 2, p2.y + 3);
    }

    if (zufall === 5) { //circleMode

      randomCircle = true;

      stroke(colR * randColor, colG * randColor, colB, alpha);
      //numlines = 100;
      strokeWeight(0.6);
      circle(p1.x - width / 4, p1.y - height / 4, p2.x / 2, p2.y);
      stroke(0);
      circle(p1.x - width / 4, p1.y - height / 4 + 1, p2.x / 2, p2.y + 3);

      //numLines = 200;
      changeColor += 0.1;
      stroke(changeColor * randColor, colG * randColor, colB, alpha);
      strokeWeight(0.8);
      circle(p1.x, p1.y, p2.x / 2, p2.y);
      stroke(0);
      circle(p1.x, p1.y + 1, p2.x / 2, p2.y + 3);

      //numLines = 100;
      stroke(colR * randColor, colG * randColor, colB, alpha);
      strokeWeight(0.6);
      circle(p1.x + width / 4, p1.y + height / 4, p2.x / 2, p2.y);
      stroke(0);
      circle(p1.x + width / 4, p1.y + height / 4 + 1, p2.x / 2, p2.y + 3);
    }

     if (zufall === 4) { //circleMode

      randomCircle = true;
      
      stroke(colR * randColor, colG * randColor, colB, alpha);
      //numlines = 100;
      strokeWeight(0.2);
      circle(p1.x - width / 4, p1.y + height / 4, p2.x / 2, p2.y);
      stroke(0);
      circle(p1.x - width / 4, p1.y + height / 4 + 1, p2.x / 2, p2.y + 3);

      //numLines = 2000;
      changeColor += 0.1;
      stroke(changeColor * randColor, colG * randColor, colB, alpha);
      strokeWeight(0.8);
      circle(p1.x, p1.y, p2.x / 2, p2.y);
      stroke(0);
      circle(p1.x, p1.y + 1, p2.x / 2, p2.y + 3);

      //numLines = 100;
      stroke(colR * randColor, colG * randColor, colB, alpha);
      strokeWeight(0.2);
      circle(p1.x + width / 4, p1.y - height / 4, p2.x / 2, p2.y);
      stroke(0);
      circle(p1.x + width / 4, p1.y - height / 4 + 1, p2.x / 2, p2.y + 3);
    }

    if (zufall >= 0 && zufall <= 3) { //lineMode

      randomLines = true;

      stroke(colR * 4, colG * 2, colB, 255);
      strokeWeight(0.1);
      numLines = 2500;
      line(p1.x * lineY, p1.y, p2.x, p2.y);
      stroke(0);
      //moveX = moveXY;
      line(p1.x * lineY, p1.y + 3, p2.x, p2.y);
      line(p1.x * lineY, p1.y + 4, p2.x, p2.y);
      line(p1.x * lineY, p1.y + 5, p2.x, p2.y);
    }

    if (line1) {
      p1.y += amplitude * sin(angleOffset / 5);
      p2.y += amplitude * sin(angleOffset / 5);

      rect(p1.x * lineX + 20, p1.y, p2.x, p2.y)
      rect(p1.x * lineX + 20, p1.y + 4, p2.x, p2.y)
    }

    stroke(colR, colG, colB, alpha * 2);
    strokeWeight(0.9);
    noFill();

    p1.y += amplitude * sin(angleOffset * 2);
    p2.y += amplitude * sin(angleOffset * 2);

    if (line2) {
      line(p1.x * lineX + 20, p1.y + 2, p2.x, p2.y + 40);
    }

    if (numLines < maxNumLines) {
      // numLines += 0.001;
    }
  }

  stroke(255, 255, 240);
  strokeWeight(100);
  noFill();
  rect(-width / 2, -height / 2, width, height);

  stroke(253, 245, 230);
  strokeWeight(95);
  noFill();
  rect(-width / 2, -height / 2, width, height);

  if (stopped) {
    // Animation nach dem Stoppen
    rectColor.levels[1] = (rectColor.levels[1] + 1) % 256;
  }

  angleOffset += 0.3; //random(0.05, 0.15);
}

function initializeParameters() {
  radius = width / width / 5500;
  angleOffset = R.random_num(1,360);
  moveX = R.random_num(0.1, 5);
}

// Funktion, um das Zeichnen nach einer bestimmten Zeit zu stoppen
function stopDrawing() {
  stopped = true;
  //noLoop();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}
